server <- function(input, output, session) {
  
  # waarschuwing per blok (alleen bij "Nee")
  waarschuwing_beloning <- reactive({
    rijen <- alle_vragen[alle_vragen$element_idx == 6, ]
    antwoorden_vec <- sapply(rijen$vraag_id, function(id) input[[id]])
    sum(antwoorden_vec == "Nee", na.rm = TRUE) >= 2
  })
  
  output$extra_warn_6 <- renderUI({
    if (waarschuwing_beloning()) {
      div(
        style = "background:#f8d7da;border-left:4px solid #C0392B;
               padding:10px 14px;margin-bottom:10px;
               border-radius:6px;font-size:13px;color:#842029;",
        "❗ Waarschuwing: bij 2 of meer 'Nee' binnen deze groep bestaat een verhoogd risico op schijnzelfstandigheid." )
    }
  })
  
  antwoorden <- reactive({
    sapply(alle_vragen$vraag_id, function(vid) {
      val <- input[[vid]]
      if (is.null(val) || val == "") NA_character_ else val
    })
  })
  
  ja_pct <- reactive({
    a <- antwoorden()
    round(sum(a == "Ja", na.rm = TRUE) / TOTAAL_VRAGEN * 100, 1)
  })
  
  output$pct_hidden <- renderText({ ja_pct() })
  
  output$voortgang_tekst <- renderUI({
    beantwoord <- sum(!is.na(antwoorden()))
    p(class = "voortgang-tekst",
      paste0(beantwoord, " van de ", TOTAAL_VRAGEN,
             " vragen beantwoord \u2014 ", ja_pct(), "% Ja")
    )
  })
  
  output$status_ui <- renderUI({
    pct <- ja_pct()
    if (pct >= DREMPEL) {
      p(class = "status-ok",
        paste0(pct, "% Ja"))
    } else {
      p(class = "status-nok",
        paste0(pct, "% Ja"))
    }
  })
  
  output$download_ui <- renderUI({
    actionButton(
      "toon_rapport",
      "Open rapport",
      class = "shiny-download-link"
    )
  })
  maak_rapport_html <- reactive({
    
    a      <- antwoorden()
    ja_n   <- sum(a == "Ja",  na.rm = TRUE)
    nee_n  <- sum(a == "Nee", na.rm = TRUE)
    leeg_n <- sum(is.na(a))
    pct    <- round(ja_n / TOTAAL_VRAGEN * 100, 1)
    datum  <- format(Sys.time(), "%d-%m-%Y %H:%M")
    
    naam <- input$naam_persoon
    aandacht <- input$aandachtspunten
    
    extra_info_html <- sprintf(
      "<div style='margin-top:10px;font-size:13px;color:#444;'>
     <strong>Naam / persoon:</strong> %s<br><br>
     <strong>Aandachtspunten:</strong><br>%s
   </div>",
      ifelse(is.null(naam) || naam == "", "-", naam),
      ifelse(is.null(aandacht) || aandacht == "", "-", gsub("\n", "<br>", aandacht))
    )
    
    pct_kleur <- if (pct <= 50) {
      ROOD
    } else if (pct <= 65) {
      "#f39c12"
    } else {
      GROEN
    }
    
    logo_html <- if (!is.null(logo_base64_string)) {
      sprintf(
        "<img src='%s' style='max-height:60px;max-width:200px;object-fit:contain;'>",
        logo_base64_string
      )
    } else ""
    
    alle_opmerkingen <- sapply(seq_len(nrow(alle_vragen)), function(i) {
      ei  <- alle_vragen$element_idx[i]
      ri  <- match(i, which(alle_vragen$element_idx == ei))
      oid <- paste0("o_", ei, "_", ri)
      val <- input[[oid]]
      if (is.null(val) || trimws(val) == "") "" else trimws(val)
    })
    
    groepen_html <- paste0(sapply(seq_along(elementen), function(ei) {
      
      el    <- elementen[[ei]]
      rijen <- alle_vragen[alle_vragen$element_idx == ei, ]
      
      kop <- sprintf(
        "<tr><td colspan='2' style='padding:10px 14px 6px;font-size:11px;font-weight:700;
       color:%s;border-top:2px solid %s;background:%s;'>%s</td></tr>",
        BLAUW, LICHTBLAUW, LICHTBLAUW, el$titel
      )
      
      vraag_rijen <- paste0(sapply(seq_len(nrow(rijen)), function(ri) {
        
        vid       <- rijen$vraag_id[ri]
        i_global  <- which(alle_vragen$vraag_id == vid)
        ant       <- ifelse(is.na(a[vid]) | a[vid] == "", "Niet ingevuld", a[vid])
        opmerking <- alle_opmerkingen[i_global]
        
        ant_kleur <- switch(ant, "Ja" = GROEN, "Nee" = ROOD, "#888888")
        ant_label <- switch(ant,
                            "Ja"  = "✔ Ja",
                            "Nee" = "✘ Nee",
                            "– Niet ingevuld")
        
        opmerking_html <- if (opmerking != "") {
          sprintf("<div style='font-size:12px;color:#666;margin-top:5px;'>%s</div>", opmerking)
        } else ""
        
        waarschuwing_check <- if (ant == "Nee") {
          "<span style='color:#C0392B;font-weight:900;font-size:18px;'>!</span>"
        } else {
          ""
        }
        
        sprintf(
          "<tr>
   <td style='padding:10px;'>%s%s</td>
   <td style='padding:10px;color:%s;'>%s</td>
   <td style='padding:10px;text-align:center;'>%s</td>
  </tr>",
          rijen$vraag_tekst[ri],
          opmerking_html,
          ant_kleur,
          ant_label,
          waarschuwing_check
        )
        
      }), collapse = "")
      
      paste0(kop, vraag_rijen)
      
    }), collapse = "")
    
    html <- sprintf('<!DOCTYPE html>
<html lang="nl">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ZZP Checklist</title>
<link href="https://fonts.googleapis.com/css2?family=Nunito:wght@300;400;600;700;900&display=swap" rel="stylesheet">
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: "Nunito", "Segoe UI", Arial, sans-serif;
    background: #f4f6fb;
    color: #222;
  }

  .page {
    max-width: 740px;
    margin: 36px auto;
    background: #fff;
    border-radius: 14px;
    padding: 36px 42px;
    box-shadow: 0 2px 18px rgba(86,106,176,0.10);
  }

  .pdf-knop-wrap {
    text-align: right;
    margin-bottom: 22px;
  }

  .pdf-knop {
    background: %s;
    color: #fff;
    border: none;
    border-radius: 9px;
    padding: 10px 22px;
    font-size: 14px;
    font-weight: 700;
    cursor: pointer;
  }

  .rapport-header {
    display: flex;
    justify-content: space-between;
    border-bottom: 2px solid %s;
    padding-bottom: 18px;
    margin-bottom: 26px;
  }

  .rapport-header h1 {
    font-size: 21px;
    color: %s;
  }

  .stats {
    display: flex;
    gap: 12px;
    margin-bottom: 26px;
  }

  .stat {
    flex: 1;
    padding: 14px;
    border-radius: 10px;
    text-align: center;
    background: %s;
  }

  .stat-num {
    font-size: 26px;
    font-weight: 900;
    color: %s;
  }

  .balk-wrap {
    background: #dde3f0;
    border-radius: 8px;
    height: 13px;
    margin-bottom: 10px;
  }

  .balk {
    height: 13px;
    background: %s;
    width: %s%%;
  }

  table {
    width: 100%%;
    border-collapse: collapse;
  }

  td {
    padding: 10px;
    border-bottom: 1px solid #eee;
  }

  .footer {
    margin-top: 20px;
    font-size: 11px;
    color: #999;
    text-align: center;
  }

</style>
</head>
<body>

<div class="page">

  <div class="pdf-knop-wrap">
    <button class="pdf-knop" onclick="window.print()">Opslaan als PDF</button>
  </div>

  <div class="rapport-header">
    <div>
      <h1>ZZP Checklist– rapport</h1>
      <div style="font-size:12px;color:#999;">%s</div>
      %s
    </div>
    %s
  </div>

  <div class="stats">
    <div class="stat">
      <div class="stat-num">%s%%</div>
      <div>Ja-percentage</div>
    </div>
  </div>

  <div class="balk-wrap">
    <div class="balk"></div>
  </div>

<table>
  <thead>
    <tr>
      <th>Stelling / opmerking</th>
      <th style="width:110px;">Antwoord</th>
      <th style="width:140px;">
        Pas op!<br>Vergrootte kans op schijnzelfstandigheid
      </th>
    </tr>
  </thead>
  <tbody>
    %s
  </tbody>
</table>

  <div class="footer">%s · %s</div>

</div>
</body>
</html>',
                    BLAUW,
                    BLAUW,
                    BLAUW,
                    LICHTBLAUW,
                    pct_kleur,
                    pct_kleur, pct,
                    datum, extra_info_html, logo_html,
                    pct,
                    groepen_html,
                    ORG_NAAM, datum)
    html  
  })
  observeEvent(input$toon_rapport, {
    
    html <- maak_rapport_html()
    
    session$sendCustomMessage(
      "openReport",
      list(html = html)
    )
  })
}

shinyApp(ui, server)
